var t=`0963-omurice`;var n=`world-0963`;var o=`JP`;var a=`east-asia`;var r=4;var s=57;var l={en:`Omurice`,ua:`Омурайсу`};var d={en:`Omurice is a Japan dish made with jasmine rice, chicken thigh, yellow onion, carrot. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Омурайсу, страва кухні країни Японія. Основні складники: рис жасмин, куряче стегно, жовта цибуля, морква. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 22 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 22 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:22,i:[[`jasmine-rice`,390,`g`],[`water`,710,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`chicken-thigh`,370,`g`],[`yellow-onion`,180,`g`],[`carrot`,155,`g`],[`frozen-green-peas`,100,`g`],[`canola-oil`,40,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`ketchup`,125,`g`],[`unsalted-butter`,35,`g`]]},{en:`Cook the beaten eggs in a thin tender omelet, slide it around the ketchup-fried rice mound and shape into an oval.`,ua:`Приготуйте ніжний тонкий омлет зі збитих яєць, огорніть ним гірку рису з кетчупом і надайте овальної форми.`,t:[`pan-frying`],m:12,i:[[`chicken-egg`,5,`pcs`],[`whole-cow-milk`,50,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:6,i:[[`ketchup`,60,`g`]]}];var g={slug:t,id:n,country:`JP`,region:a,servings:4,minutes:57,title:l,text:d,steps:h};export{o as country,g as default,n as id,s as minutes,a as region,r as servings,t as slug,h as steps,d as text,l as title};